SELECT DISTINCT ud.user_id FROM user_dept ud INNER JOIN dept_closure dc ON ud.dept_id = dc.descendant_id INNER JOIN sys_dept d ON d.id = dc.descendant_id AND d.is_deleted = 0 WHERE dc.ancestor_id IN
#{deptId}
AND ud.status IN (1, 2)

SELECT DISTINCT up.user_id FROM user_post up WHERE up.post_id IN
#{postId}
AND up.status IN (1, 2)

SELECT DISTINCT r.role_code FROM role_policy rp INNER JOIN sys_role r ON r.id = rp.role_id INNER JOIN user_access_policy_definition d ON d.id = rp.policy_id WHERE d.policy_code IN
#{policyCode}
AND rp.is_deleted = 0

SELECT DISTINCT b.user_id FROM user_access_policy_binding b INNER JOIN user_access_policy_definition d ON d.id = b.policy_id WHERE d.policy_code IN
#{policyCode}
AND b.is_deleted = 0
